  // ═════════ Threats: ATT&CK techniques WS-X90's risks name, and the controls that counter them ═════════
  const TT = D.tt.map(([c, t, m, tac, risks, ctl]) => ({ code: c, t, m, tac, risks, ctl: ctl.map((k) => ({ code: k, ...stand(k) })) }));
