  const ICS = { ...D.ics, ex: true, ctl: D.ics.ctl.map(([k, title, base, obj = 0, mapped = 0, ev = 0, as = 0]) => ({ code: k, title, base: !!base, obj, mapped, ev, as })) };
  const TECHS = [...TT, ICS];
