  const tsum = (t) => { const inb = t.ctl.filter((c) => c.base); return { n: t.ctl.length, inb: inb.length, obj: inb.reduce((s, c) => s + c.obj, 0), mapped: inb.reduce((s, c) => s + c.mapped, 0) }; };
