    const facts = AK.facts([["WS-X90 status", k ? csPill(k.cs) : mu("Not in the baseline")], ...(x.obj ? [["Objectives mapped", of(x.mapped, x.obj)], ["With evidence", of(x.ev, x.obj)], ["Assessed", of(x.as, x.obj)]] : []), ["Requirements", x.base ? `${num(x.reqs)} ${mu(`· ${x.evr} with evidence`)}` : mu("None")]]);
